sc_cat_item_producer.script:
/** This script is executed before the Record is generated
 * `current`- GlideRecord produced by Record Producer
 * Don't use `current.update()` or `current.insert()` as the record is generated by Record Producer
 * Don't use `current.setValue('sys_class_name', 'xxx')` as this will trigger reparent flow and can cause data loss
 * Avoid `current.setAbortAction()` and generate a separate record
 * Use `producer.var1` to access variables
 * 
 * 
 */

var response = [{
    "tradeRef": "D-58907-00-0",
    "tradeMarket": "DCC HK",
    "inValidReason": "Duplicate Trade Reference found for D-58907-00-0."
}, {
    "tradeRef": "D-5856707-00-0",
    "tradeMarket": "DCC HK",
    "inValidReason": "Trade Reference provided does not exist in iQube Database."
}];
gs.info(" Hello " + current.sys_id);
gs.info(" Hello 2" + response);

// if (errors.length > 0) {
spModal.open({
    title: 'Validation Errors',
    size: 'lg',
    widget: 'display_bulk_errors_widget',
    widgetInput: {
        errorList: response
    }
});
current.setAbortAction(true);








